/// <summary>
/// The NVTrvWorkerExpenseReqWFTypeEventHandler workflow event handler.
/// </summary>
public class  NVTrvWorkerExpenseReqWFTypeEventHandler implements WorkflowCanceledEventHandler,  
	WorkflowCompletedEventHandler,
	WorkflowStartedEventHandler
{
}

Method.Source:
    public void completed(WorkflowEventArgs _workflowEventArgs)
    {
        RecId                       trvExpenseRecId = _workflowEventArgs.parmWorkflowContext().parmRecId();
        NVTrvWorkerExpenseRequest   trvExpense      = NVTrvWorkerExpenseRequest::find(trvExpenseRecId);

        if(trvExpense)
        {
            NVTrvWorkerExpenseRequest::updateWorkflowStatus(trvExpense.RecId, NVTrvWorkerExpReqWFStatus::Approved);

            NVTimesheetChangeHandler::insertNewRef(trvExpense.Worker, trvExpense.TableId, trvExpense.RecId);
        }
	}
